// Eight DISTINCT rows are a clique in the pair compatibility graph (no vertex repeats).
use std::{collections::HashMap,io::{self,Read}};type A=[u32;26];const F:u32=(1<<26)-1;
fn witness(a:&A,mut p:u32,k:u32)->Option<u32>{if k==0{return Some(0)}while p.count_ones()>=k{let i=p.trailing_zeros()as usize;let bit=1<<i;p^=bit;if let Some(q)=witness(a,p&!a[i],k-1){return Some(q|bit)}}None}
fn clique(g:&[Vec<bool>],opts:&[usize],k:usize)->Option<Vec<usize>>{if k==0{return Some(vec![])}for (p,&i)in opts.iter().enumerate(){if opts.len()-p<k{break}let q:Vec<_>=opts[p+1..].iter().copied().filter(|&j|g[i][j]).collect();if let Some(mut v)=clique(g,&q,k-1){v.push(i);return Some(v)}}None}
fn graph(a:&A,es:&[(usize,usize)],mut m:u64)->A{let mut b=*a;while m!=0{let k=m.trailing_zeros()as usize;m&=m-1;let(i,j)=es[k];b[i]^=1<<j;b[j]^=1<<i}b}
fn main(){let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let mut it=s.lines().map(|l|l.split_whitespace().map(|x|x.parse::<u32>().unwrap()).collect::<Vec<_>>());let a:A=it.next().unwrap().try_into().unwrap();let rows=it.next().unwrap();let n=rows.len();let mut es=vec![];let mut cuts=vec![0u64;n];for i in 0..26{for j in i+1..26{if a[i]>>j&1==0{continue}let ids:Vec<_>=(0..n).filter(|&t|rows[t]>>i&rows[t]>>j&1!=0).collect();if ids.len()>0{let k=es.len();assert!(k<64);es.push((i,j));for t in ids{cuts[t]|=1<<k}}}}let mut cache=HashMap::new();let mut legal=|m|->Option<A>{*cache.entry(m).or_insert_with(||{let b=graph(&a,&es,m);if witness(&b,F,8).is_none(){Some(b)}else{None}})};
let mut g=vec![vec![false;n];n];let mut h=g.clone();let mut counts=[0u64;2];for i in 0..n{for j in i+1..n{if witness(&a,F&!(rows[i]|rows[j]),7).is_some(){continue}g[i][j]=true;counts[0]+=1;if legal(cuts[i]|cuts[j]).is_some(){h[i][j]=true;counts[1]+=1}}}let opts:Vec<_>=(0..n).collect();for gr in [&g,&h]{println!("{:?}",clique(gr,&opts,8).unwrap_or_default())}println!("{:?}",counts);
let mut tested=0u64;for i in 0..n{for j in i+1..n{if !h[i][j]{continue}for k in j+1..n{if !h[i][k]||!h[j][k]{continue}if let Some(b)=legal(cuts[i]|cuts[j]|cuts[k]){tested+=1;for(x,y,z)in [(i,j,k),(i,k,j),(j,k,i)]{if let Some(q)=witness(&b,F&!(rows[x]|rows[y]),7){println!("{} {} {} {} {}",x,y,z,q,tested);return}}}}}}println!("none {}",tested)}
